insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 1, 'Which of the four length change effects is usually the largest in a producing well?', '["Buckling, because it is nonlinear.", "Temperature, because the coefficient is small and the string is kilometres long.", "Ballooning, because internal pressure acts over the whole bore area and the pressures involved are tens of megapascals.", "The piston effect, because the area changes at the seal assembly and the packer are large in a full bore completion."]'::jsonb, 1, 'A change of tens of degrees over kilometres of steel is metres of length.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 2, 'What does ballooning do to the length of a tubing string?', '["Internal pressure swells it radially and therefore shortens it axially.", "Internal pressure lengthens it axially.", "It has no axial effect at all, because the radial and axial strains are independent for a thin walled cylinder under pressure.", "It shortens the string only where the internal pressure exceeds the external pressure by more than the yield stress of the steel."]'::jsonb, 0, 'External pressure does the reverse.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 3, 'Why does buckling shorten a string?', '["Because buckled pipe is compressed and steel compresses.", "Because a buckled string bears on the casing wall, and the friction that develops holds part of its length in compression.", "Because a helix is shorter end to end than a straight line of the same pipe.", "Because buckling occurs only under cooling, so the shortening observed is the thermal contraction rather than the buckling."]'::jsonb, 2, 'And it does so nonlinearly, which is what makes it the awkward one of the four.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 4, 'What does this course do with the four effects?', '["It computes all four from the well conditions.", "It computes the thermal effect and takes the other three as inputs, since the thermal one dominates in most producing wells.", "It computes them all but reports only the total, because the individual contributions are not separable in a real string.", "Nothing; it takes a length change as an input and asks a geometric question."]'::jsonb, 3, 'Computing them needs a temperature profile, a pressure profile, a fluid density and a survey.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 5, 'Which course supplies the length changes this tier is designed against?', '["Casing and Tubing Design, which ends on three tubing load cases.", "Torque and Drag, which computes the axial force profile.", "Well Control, which supplies the pressures that the tubing string is exposed to during a kick and during the kill that follows.", "Geomechanics, which supplies the temperature profile of the formation from which the string temperature is then derived."]'::jsonb, 0, 'The engine that computed those numbers has its own goldens and its own oracle.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 6, 'What is the shape of the three borrowed cases?', '["Two elongations and one contraction.", "One elongation and two contractions, with the largest magnitude a contraction.", "Three contractions of increasing magnitude, corresponding to production, injection and stimulation in that order of severity.", "One elongation, one contraction and one case with no net length change at all, where the four effects cancel each other out."]'::jsonb, 1, 'Producing warms a well moderately and pumping a cold fluid at rate cools it far more.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 7, 'Roughly how large is the swing across the three borrowed cases?', '["About half a metre.", "About one and a half metres, which is the stroke of the seal arrangement the other course used for the same string.", "A little over four metres.", "About ten metres, which is why a polished bore receptacle rather than a seal stroke is required for that completion."]'::jsonb, 2, 'That is the number a bore has to accommodate, plus margin at both ends.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 8, 'Why borrow the length changes rather than recompute them here?', '["Because the calculation is too slow to run twice.", "Because the other course computes them at a different set of conditions, which this course would not be able to reproduce.", "Because the length changes are proprietary to the vendor of the tubing and cannot be recomputed from published data.", "Because a second implementation would be a second thing to validate and to disagree with the first."]'::jsonb, 3, 'It is the same discipline that makes the casing program an input rather than something this course invents.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 9, 'What is the cost of anchoring the tubing to the packer?', '["The length change becomes a force, and the string has to survive it.", "The seals have to be replaced more often.", "The packer has to be set deeper, because an anchored string transfers its whole weight to the packer rather than to the hanger.", "The string cannot be recovered later without cutting it, since an anchored connection cannot be released from surface."]'::jsonb, 0, 'The benefit is simplicity: no moving seals, nothing to leak, nothing to space out.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 10, 'What is the limitation of a seal arrangement with a finite stroke?', '["It cannot hold pressure from below.", "When a case exceeds the stroke the seals shoulder and the string starts loading up.", "It can only absorb contraction, because the seals are free to move upward but are stopped by a shoulder in the other direction.", "It has to be set at the midpoint of the stroke, which leaves only half the travel available in each direction."]'::jsonb, 1, 'Two of the three borrowed cases stroked out of a one and a half metre stroke.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 11, 'What does a polished bore receptacle cost, and what does it buy?', '["It costs nothing and buys unlimited travel.", "It costs a reduction in the through bore of the string, and it buys the ability to release the string from the packer at surface.", "It costs length and money; it buys enough travel to carry every case and a choice of landing.", "It costs a larger outside diameter at the packer, and it buys the ability to hold pressure from both directions at once."]'::jsonb, 2, 'It is the third approach, and the one with a design decision in it.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 12, 'Which boundary condition has zero displacement at the bottom of the string?', '["Free, where the seals slide in a long bore.", "Limited, where the seals can move some distance and then cannot move any further in that particular direction.", "All three, because the packer itself does not move and the bottom of the string is attached to it in every arrangement.", "Anchored, where the tubing is latched into the packer and cannot move."]'::jsonb, 3, 'Length change turns entirely into force, and the string is statically indeterminate.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 13, 'In which arrangement does a temperature change put no axial load into the packer at all?', '["Free, where the seals never reach either end of the bore.", "Anchored, where the string cannot move at all.", "Limited, where the string is free until the travel is used up and anchored afterwards, so the average force is close to zero.", "None of them, because a piston force always acts across the seal area whatever the boundary condition happens to be."]'::jsonb, 0, 'A piston force from the pressure differential still acts; the length change contributes nothing.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 14, 'Why can the same completion be in different regimes for different operations?', '["Because the packer setting changes with temperature.", "Because available travel is fixed by the hardware and the length change varies by operation.", "Because the seals wear over time, so a string that starts free becomes limited as the seal stack loses its ability to slide.", "Because the boundary condition is chosen at surface by the operator before each operation and can be changed between them."]'::jsonb, 1, 'A well can be free through its whole production life and become anchored in the middle of a stimulation.'),
  ('completion', 'advanced', 'module', 'm01-a-completion-is-not-static', 15, 'What is the design goal for the space out?', '["Keep the string anchored under all conditions.", "Land the seals at the midpoint of the bore, which balances the two directions and is the standard practice for this reason.", "Keep every case the well will see in the free regime, with margin.", "Choose a bore just long enough for the largest case, so that no money is spent on travel that will never be used."]'::jsonb, 2, 'Then the completion never loads up and the seals never reach a shoulder.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 1, 'What is a polished bore receptacle?', '["A seal element that expands against the casing.", "A machined internal profile in the tubing that a lock mandrel latches into, so that a plug can be set at a known depth.", "A length of pipe with a honed internal bore, made up above the packer, that does not move.", "A sliding sleeve run immediately above the packer, which allows the annulus to be circulated before the packer is set."]'::jsonb, 2, 'Its length is the thing this tier cares about.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 2, 'What does the seal assembly do inside the receptacle?', '["It seals against the polished bore and slides, without gripping it.", "It grips the bore and holds the string in place.", "It expands into a machined recess in the bore, which locks it at a known depth and prevents any relative movement afterwards.", "It is cemented into the bore during the completion operation, so that the seal is permanent for the life of the well."]'::jsonb, 0, 'Pressure integrity without a mechanical connection is the design intent.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 3, 'How is insertion depth defined?', '["The distance from the seals to the bottom of the bore.", "The distance from the top of the receptacle down to the seals.", "The distance from the packer to the seals, which includes the length of any pup joints run between the two components.", "The fraction of the receptacle length that lies above the seal stack, expressed as a proportion rather than as a length."]'::jsonb, 1, 'The published job lands three metres into a six point one metre bore.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 4, 'The seals are three metres into a six point one metre bore. What travel is available in each direction?', '["Six point one metres in both directions.", "Three point zero five metres in each direction, since the bore is divided equally between the two whatever the landing is.", "Three point one metres of contraction and three metres of elongation, since elongation is measured from the top downward.", "Three metres of contraction and three point one metres of elongation."]'::jsonb, 3, 'Choosing the insertion depth chooses how the bore is divided between them.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 5, 'What physically sets the insertion depth on the rig?', '["The accumulated length of everything above the seal assembly in the tally.", "A setting tool run on wireline after the packer is set.", "The design document, which specifies the insertion depth and which the crew reproduces by adjusting the packer setting depth.", "The hanger, which can be landed at several elevations in the wellhead to give a range of insertion depths after the fact."]'::jsonb, 0, 'To land two metres deeper, you add two metres of pipe above.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 6, 'Why does a completion carry pup joints?', '["Because they are cheaper than full joints.", "Because full joints are far too coarse to space out a bore of a few metres.", "Because a pup joint is machined to a tighter tolerance than a full joint, which is required at the bottom of the string.", "Because they provide the extra wall thickness needed immediately above the seal assembly, where the loads are largest."]'::jsonb, 1, 'A typical set gives increments of a foot or less against a bore of several metres.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 7, 'Why is the space out computed on the rig rather than in the office?', '["Because the office does not have the well data.", "Because the packer setting depth is only known once the packer has been set, and the space out depends on where it landed.", "Because the measured joint lengths differ from the nominal ones on the tally.", "Because the temperature of the string at the time of landing affects its length and can only be measured at the wellsite."]'::jsonb, 2, 'It is an operation and not a desk calculation.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 8, 'The string comes out a metre longer than the tally said. What happens to the two available travels?', '["Both gain half a metre.", "Both are unaffected, because the extra length is taken up above the seal assembly rather than inside the receptacle itself.", "Both lose a metre, because the extra length has to be accommodated somewhere and the bore is the only place available.", "One gains a metre and the other loses one, in opposite directions."]'::jsonb, 3, 'If the design was balanced, it is now unbalanced, usually towards the direction that matters most.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 9, 'State the budget identity.', '["Available travel up plus available travel down equals the receptacle length, at every landing.", "The two travels are equal at every landing.", "The sum of the two travels equals the receptacle length less the length of the seal stack itself, which occupies part of it.", "The product of the two travels is maximised at the midpoint of the bore, which is why the midpoint is the standard landing."]'::jsonb, 0, 'The seals are somewhere in the bore, and the distances to the two ends sum to its length.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 10, 'What does the budget identity rule out?', '["Landing anywhere other than the midpoint.", "Solving for one case and then the other, and landing at both.", "Using a receptacle longer than the swing, since the extra length cannot be divided between the two directions usefully.", "Computing the two available travels separately, since neither can be found without knowing the other one first."]'::jsonb, 1, 'Every millimetre gained in one direction is a millimetre lost in the other, at an exchange rate of exactly one.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 11, 'Define available, used and remaining.', '["Available is the bore length and used is the insertion depth.", "Available is the travel in that direction, used is the fraction of it consumed, and remaining is the fraction still unused.", "Available is the travel in that direction, used is the case magnitude, remaining is the difference.", "Available is the whole bore, used is the sum of both case magnitudes, and remaining is what is left after both have occurred."]'::jsonb, 2, 'Remaining is the only one of the three that depends on both the hardware and the operation.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 12, 'Which of the three quantities depends on the landing and not on the case?', '["Used, which is fixed by the hardware.", "Remaining, since it is computed from the available travel and therefore inherits its dependence on where the seals were landed.", "None of the three, because all three are functions of both the landing and the operation being considered.", "Available."]'::jsonb, 3, 'Used depends on the case and not at all on the landing, and remaining depends on both.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 13, 'The published contraction case has two tenths of a metre remaining against a half metre margin. What is the verdict?', '["A warning, because the remaining travel is positive and below the margin.", "A failure, because it is below the margin.", "A pass, because the remaining travel is positive and the seals therefore stay inside the polished bore throughout the case.", "Undefined, because a margin of half a metre cannot be applied to a case whose remaining travel is smaller than it is."]'::jsonb, 0, 'The same three verdict structure as the clearance check, on the same kind of question.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 14, 'Which two inputs does the space out calculation refuse?', '["A negative length change, and a margin of zero.", "An insertion deeper than the bore, and a bore of zero length or less.", "A length change larger than the bore, and an insertion depth of zero, both of which describe an unusable landing.", "A margin larger than half the bore length, and any case in which the two length changes have the same sign."]'::jsonb, 1, 'Both are input errors rather than design outcomes.'),
  ('completion', 'advanced', 'module', 'm02-the-polished-bore-receptacle', 15, 'What does the space out margin protect against?', '["A bore smaller than the catalog value.", "The seals wearing over the life of the well, which reduces the effective travel available in both directions over time.", "A length change larger than computed, and a landing other than intended.", "The packer moving, which changes the position of the receptacle and therefore the landing relative to the string above."]'::jsonb, 2, 'Both are substantial uncertainties: a predicted temperature profile and a few hundred measured joint lengths.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 1, 'The string lengthens. Which way do the seals move relative to the receptacle?', '["Out of it, towards the top of the bore.", "Deeper into it, because the top is fixed and the extra length goes downward.", "They do not move, because the receptacle is attached to the packer and moves with the string as the string changes length.", "It depends on whether the string is in tension or compression at the point where the seal assembly is made up to it."]'::jsonb, 1, 'The top cannot move, so the extra length has nowhere else to go.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 2, 'Which travel does elongation consume?', '["The receptacle length less the insertion depth.", "The insertion depth itself.", "The whole receptacle length, since the seals may travel from wherever they are to either end of the bore during the case.", "Half the receptacle length, because the travel is shared equally between the two directions whatever the landing was."]'::jsonb, 0, 'That is the bore below the seals, and it is where the sign errors live.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 3, 'What happens when elongation exceeds the available travel?', '["The seals come out of the top of the bore.", "Nothing happens, because a polished bore receptacle has no shoulder and the seals simply continue past the end of the bore.", "The seal assembly shoulders at the bottom and the string starts to load up in compression.", "The packer unseats, because the compressive load transferred through the shoulder exceeds what the slips can carry."]'::jsonb, 2, 'It is a transition from free to anchored, and often survivable.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 4, 'A cooling job pulls the seals up. What limits how far they can go?', '["The receptacle length less the insertion depth.", "The whole receptacle length, less the length of the seal stack, which cannot leave the bore without losing integrity first.", "Whatever remains after the elongation case has been accounted for, since the two cases are considered in sequence.", "The insertion depth itself."]'::jsonb, 3, 'That is the cleanest statement in this tier.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 5, 'A cooling job pulls the seals past that limit. What is the result?', '["The seals come out of the bore and the tubing to annulus seal is lost.", "The seals shoulder at the top of the bore.", "The string goes into tension against the packer, and the load has to be carried by the connection between the two.", "The seal stack is damaged but remains inside the bore, so integrity is maintained until the next intervention on the well."]'::jsonb, 0, 'There is no shoulder to stop them and nothing to load up against.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 6, 'Why is the contraction failure more serious than the elongation failure?', '["Because contraction is harder to predict.", "Because it is a loss of containment rather than a transfer of load.", "Because the elongation failure occurs slowly over the producing life while the contraction failure occurs during a single job.", "Because the elongation failure can be detected at surface from the hook load, while the contraction failure cannot be detected."]'::jsonb, 1, 'It happens during a stimulation with pumps running and does not announce itself until pressure appears where it should not.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 7, 'Across the three borrowed cases, how do the largest elongation and the largest contraction compare?', '["They are within a few percent of each other.", "The elongation is about twice the contraction, because production heating raises the string temperature more than cooling lowers it.", "The contraction is nearly four times the elongation.", "The contraction is about ten times the elongation, which is why a seal stroke was never a viable arrangement for that string."]'::jsonb, 2, 'Both the severity and the magnitude point the same way.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 8, 'The published job lands almost exactly in the middle of its bore. When would that be right?', '["Always, because the midpoint is the balanced landing.", "When the elongation case is the larger of the two, since the midpoint then leaves extra travel in the direction that needs it.", "When the margin is small relative to the bore, in which case the exact landing matters little and the midpoint is adequate.", "If the two cases were equal and opposite."]'::jsonb, 3, 'They are not equal, and the near miss is on the dangerous side.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 9, 'Sweep the insertion depth and plot the two remaining travels. What do you see?', '["Two straight lines with equal and opposite slopes, crossing at one point.", "Two curves that both fall with insertion depth.", "Two straight lines with the same slope, offset from each other by the difference between the two case magnitudes.", "Two lines that meet at the midpoint of the bore, which is where both directions have the same available travel."]'::jsonb, 0, 'Where one rises the other falls, at the same rate.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 10, 'What is true at the crossing point of those two lines?', '["Both cases have the same available travel.", "Both cases have the same remaining travel, which is not the same as the same available travel.", "Both cases pass with exactly the stated margin, which is what defines the crossing and makes it the recommended landing.", "The sum of the two remaining travels is at its maximum, which is why the crossing is the optimum landing for the string."]'::jsonb, 1, 'The two cases use different amounts, so equal remaining is not equal supply.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 11, 'Where does the crossing sit relative to the midpoint of the bore when contraction is the larger case?', '["Shallower, for the same reason.", "At the midpoint, because the crossing is defined by the geometry of the bore rather than by the magnitudes of the cases.", "Deeper, because the contraction direction needs more room.", "It depends on the margin, since the margin shifts both requirements equally and therefore moves the crossing point too."]'::jsonb, 2, 'The crossing is where the two are equally comfortable rather than equally supplied.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 12, 'Somebody proposes landing deeper to fix a contraction warning, checks the elongation case, and finds it still passes. What have they missed?', '["Nothing; the move is free and the problem is solved.", "That the elongation case will now fail, because the budget identity means a gain in one direction always causes a loss in the other.", "That the landing cannot be changed once the packer has been set, so the proposal is not executable in any case.", "That the elongation case lost exactly what the contraction case gained."]'::jsonb, 3, 'The move was right because there was slack in the elongation direction, not because it cost nothing.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 13, 'When is the midpoint of the bore the correct landing?', '["When the two length changes are equal and opposite.", "Whenever the bore is longer than the swing.", "Whenever the contraction case is the larger of the two, since the midpoint then favours the direction that needs the room.", "Whenever the margin is at least half the bore length, in which case any landing inside the band gives the same result."]'::jsonb, 0, 'Then the two directions need the same room and splitting evenly is right.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 14, 'What is the correct rule that replaces the midpoint of the bore?', '["Land as deep as the bore allows.", "Land in the middle of the band of acceptable landings.", "Land at the depth that makes the remaining travel in each direction proportional to the magnitude of the case in that direction.", "Land at the depth that leaves the largest single remaining travel, which maximises the protection against the worst case."]'::jsonb, 1, 'Those are different points, and the band is where both cases pass with margin.'),
  ('completion', 'advanced', 'module', 'm03-the-asymmetry', 15, 'Which of these is NOT a reason to land off the middle of the band?', '["One failure mode is more serious than the other.", "One of the two cases is far better known than the other, so leaving room against the less certain one is buying insurance.", "The bore is longer than the minimum required.", "One of the cases will not actually happen on this well, so it should not be sizing the landing in the first place."]'::jsonb, 2, 'A longer bore widens the band; it does not push the landing towards either end of it.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 1, 'What is the lower edge of the band of acceptable landings?', '["The contraction magnitude plus the margin.", "The elongation magnitude plus the margin.", "The bore length less the elongation magnitude and less the margin, which is the deepest landing the elongation case permits.", "Half the bore length, since the band is always centred on the midpoint whatever the two case magnitudes happen to be."]'::jsonb, 0, 'The contraction case sets a lower bound on the insertion depth.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 2, 'What is the upper edge?', '["The contraction magnitude plus the margin.", "The bore length less the elongation magnitude and less the margin.", "The bore length less twice the margin, since a margin has to be left at both ends of the receptacle whatever the case is.", "The bore length itself, since the seals can be landed anywhere in the bore and the upper limit is simply its bottom."]'::jsonb, 1, 'The elongation case sets an upper bound on the insertion depth.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 3, 'What is the width of the band?', '["The difference between the two case magnitudes.", "The bore length less twice the margin, since the two margins are the only part of the bore that cannot be used for landing.", "The bore length less the sum of the two requirements.", "The sum of the two remaining travels at the midpoint of the bore, which is what is left over after both cases are absorbed."]'::jsonb, 2, 'That check catches a sign error in either edge immediately.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 4, 'What does an empty band mean?', '["The landing has been computed incorrectly.", "The two cases have the same sign, so one of them is not actually a design case and the calculation should not have been run.", "The margin is larger than the bore length, which is an input error rather than a result about the design of the completion.", "The bore is too short, and no landing satisfies both cases."]'::jsonb, 3, 'The fixes are a longer bore, a smaller margin, or a shorter design case list.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 5, 'The engine finds the band by bisection rather than by solving the inequalities. Why?', '["Because the inequalities cannot be solved in closed form.", "Because bisection is faster than evaluating the two closed form expressions, which involve several conditional branches each.", "Because bisection does not assume the analytic form, and would survive a nonlinearity.", "Because the pass and fail predicate is discontinuous, and a closed form solution cannot represent a discontinuous boundary."]'::jsonb, 2, 'It is slower and it has that one advantage worth having.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 6, 'What does the band width tell you beyond where to land?', '["The tolerance on execution: how far out the space out can be and still be acceptable.", "The magnitude of the larger of the two cases.", "The length of bore that is unused in both directions, and therefore the amount by which the receptacle could be shortened.", "The number of pup joint sizes that would have to be carried in order to achieve a landing inside it on the rig floor."]'::jsonb, 0, 'A band ten centimetres wide means the pup joint selection has to be right.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 7, 'For the published job, a six point one metre bore with the published cases and margin, where is the lower band edge?', '["At one point seven metres of insertion.", "At three point three metres of insertion.", "At three point zero five metres of insertion, which is the midpoint of the bore and therefore the balanced landing for it.", "At four point four metres of insertion, which is the deepest landing that the elongation case will permit on that job."]'::jsonb, 1, 'It is the contraction magnitude plus the margin.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 8, 'On the same job, how deep may the seals be landed before the heating case is at risk?', '["At three point three metres of insertion.", "At six point one metres of insertion, since the seals can be landed anywhere down to the bottom of the receptacle itself.", "At five point one metres of insertion, which is the bore length less the elongation magnitude with no margin applied.", "At four point four metres of insertion."]'::jsonb, 3, 'The bore length less the elongation magnitude and less the margin.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 9, 'How wide is the published band, and how does that check out?', '["One point one metres, which equals the bore less the two requirements.", "Half a metre, which equals the margin.", "Three point one metres, which is the travel available to the elongation case at the published landing of three metres.", "Two point eight metres, which is the contraction case magnitude and therefore the room the band has to leave for it."]'::jsonb, 0, 'Running that check every time catches a sign error in either edge.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 10, 'Where does the midpoint of the published bore sit relative to its band?', '["Exactly at the middle of the band.", "Below the lower edge, so the rule of thumb landing is outside the band.", "Above the upper edge, because the contraction case is the larger one and therefore pushes the band shallower than the midpoint.", "Inside the band but close to its upper edge, which is why the published job passes the elongation case comfortably."]'::jsonb, 1, 'That is the striking result of this module.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 11, 'By how much does the published landing fall short of its band?', '["Half a metre, which is the margin.", "Eight tenths of a metre, which is the distance from the published landing to the middle of the band rather than to its edge.", "Three tenths of a metre.", "One point one metres, which is the width of the band and therefore the distance from its lower edge to its upper one."]'::jsonb, 2, 'On a rig floor that is one pup joint.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 12, 'Why is the shortfall the same number as the amount by which the contraction remaining falls short of the margin?', '["Because the margin happens to equal the shortfall.", "Because the two quantities are computed from the same expression, so they are equal by construction rather than by physics.", "Because the elongation case has slack, and any slack in one direction appears as an equal deficit in the other direction.", "Because both measure the same distance from the landing to the point where the case would just pass."]'::jsonb, 3, 'They are the same fact seen from two sides.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 13, 'Is the published job wrong?', '["No; it works, and it does not deliver the margin the design asked for.", "Yes; the seals come out of the bore.", "Yes; the contraction case fails outright, which is a loss of well integrity during the operation that produces it.", "No; the margin is a guideline rather than a requirement, so a landing that delivers less than it is fully compliant."]'::jsonb, 0, 'The margin was stated and not enforced.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 14, 'State the shortest usable bore length.', '["The larger of the two case magnitudes plus the margin.", "The whole swing plus twice the margin.", "The sum of the two case magnitudes, since the seals have to travel that distance and the margin is already inside the swing.", "Twice the larger case magnitude, which guarantees enough room in both directions whichever of the two turns out to dominate."]'::jsonb, 1, 'It falls out of the band identity and out of the physics, one line each.'),
  ('completion', 'advanced', 'module', 'm04-designing-the-space-out', 15, 'What does every metre of bore beyond the minimum buy?', '["One metre of extra travel in each direction.", "Half a metre of tolerance in each direction, since the extra length is divided between the two ends of the receptacle.", "One metre of band, which is one metre of tolerance on the landing.", "Nothing, because a bore longer than the minimum leaves travel that neither of the two design cases will ever use."]'::jsonb, 2, 'That is the second thing the identity tells you.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 1, 'Which numbers in this course come from a published specification?', '["The equipment outside and inside diameters.", "The four drift deduction values and the two size boundaries.", "The component lengths in the published string, which are taken from a completion tally recorded on an actual well.", "The polished bore length and the landing depth of the published space out job, both of which are field records."]'::jsonb, 1, 'Those are real and checkable, as are the casing and tubing dimensions from the API tables.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 2, 'Which calculation in this course depends on the equipment catalog not at all?', '["The space out, which depends only on a bore length, a landing and two length changes.", "The drift table.", "The through bore, which reads the component inside diameters but not their outside diameters, so the catalog only half applies.", "The volumes, since both string volumes are computed from the component lengths rather than from their diameters."]'::jsonb, 0, 'Those results are unconditional: the identity, the band and the minimum bore length are arithmetic.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 3, 'How should the statement that the packer is the tightest row be read?', '["As a number that can be quoted in a design document.", "As an artefact of the representative catalog, which would very likely reverse if real vendor dimensions were substituted in.", "As a structural fact about packers in liners, whose magnitude is illustrative.", "As a property of the published well alone, with no implication for any other completion run into a liner anywhere else."]'::jsonb, 2, 'The structure transfers and the digits do not.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 4, 'If every catalog row were replaced with real data, what would happen to the conclusions?', '["All of them would need to be rechecked.", "Only the clearance conclusions would survive, since those depend on differences rather than on the absolute dimensions used.", "The conclusions would hold for the same vendor and would have to be re established for any other one separately.", "None would reverse, because each rests on an ordering that real data preserves."]'::jsonb, 3, 'Big bodies are bigger than pipe and nipple bores are smaller than tubing bores, whoever makes them.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 5, 'The warn margin is an input rather than a constant. Why?', '["Because the right value depends on the well and on the operator''s risk appetite.", "Because the specification does not define one.", "Because the margin has to be tuned until the string reports a mixture of verdicts, which is what makes the report informative.", "Because a margin expressed as a constant would have to be given in metres, and the engine works internally in inches."]'::jsonb, 0, 'The engine reports against whatever you give it and will not tell you what to give it.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 6, 'Which of these does the engine decline to decide?', '["The governing drift to a depth.", "Which length changes belong on the design case list.", "Whether the volume integration should skip an uncovered interval or refuse the whole calculation when the program has a gap.", "Whether a component whose bore exceeds its body should be refused or accepted with a warning attached to the row."]'::jsonb, 1, 'Which cases the well will see is a judgement about its whole life, and the engine takes what it is given.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 7, 'Why does the engine not choose a point within the band for you?', '["Because the band is not always a single interval.", "Because the midpoint is always correct, so there is no choice to be made and nothing for the engine to decide about it.", "Because the choice depends on which failure is worse and how well each case is known.", "Because the landing is set on the rig by pup joint selection, so any value the engine chose could not be executed exactly."]'::jsonb, 2, 'Computing the consequence precisely and leaving the choice to the reader is the more useful division.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 8, 'What would be lost if the engine picked defaults for every choice and reported one answer?', '["Nothing; a single answer is easier to act on.", "The ability to run the calculation at all, since several of the choices cannot be given a default that works on every well.", "The validation against the oracle, which compares outputs rather than choices and would therefore no longer be meaningful.", "The reader would not know which parts of the answer were data and which were the tool''s assumptions."]'::jsonb, 3, 'A tool that made these choices would be making them from assumptions it invented.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 9, 'Which absent physics would most directly change the clearance results?', '["Deviation and doglegs, because a rigid component through a bend needs more room.", "Flow and erosion velocity.", "The thermal and pressure loads, since those change the length of the string and therefore where each component actually sits.", "Time, since scale and corrosion reduce the bore and therefore reduce every clearance in the string as the well ages."]'::jsonb, 0, 'It would need the survey, and it would also allow a running load calculation.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 10, 'Which absent physics interacts most directly with the space out results?', '["Flow, because it sets the erosion rate.", "Buckling, because it changes the length change the space out has to absorb.", "Deviation, because a deviated string moves along the hole rather than vertically and the seals therefore travel less.", "Time, because the seal elements degrade and the effective travel available reduces over the producing life of the well."]'::jsonb, 1, 'It is nonlinear, and it needs the axial force distribution, which needs the loads above it.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 11, 'What does the Expert certificate certify?', '["That the holder can design a completion.", "That the holder can compute the thermal and pressure length changes of a tubing string and check the string against them.", "A complete correct geometric assessment, and knowing where each result stops being valid.", "That the holder can select and specify completion equipment from vendor catalogs for a well of any service condition."]'::jsonb, 2, 'Plus reading a tool''s summary critically enough to check it against its own detail.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 12, 'Which of these does the Expert certificate NOT certify?', '["That the holder can build an exposed casing profile.", "That the holder can compute a through bore with its extents and interpret the difference between an extreme and an extent.", "That the holder can size a polished bore receptacle and choose a landing within the band with a stated reason for it.", "That any number in this course is quotable in a design document."]'::jsonb, 3, 'The equipment catalog is representative and flagged as such on every row.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 13, 'Why is the certificate''s claim drawn narrowly?', '["Because a wide claim on the strength of a geometry course would be worth less than nothing.", "Because the course is shorter than a full design course.", "Because the academy issues one certificate per app, and a completion design claim would overlap several other courses at once.", "Because the equipment catalog is representative, which limits what any certificate based on this course could reasonably assert."]'::jsonb, 0, 'The geometry is a real and separable skill, and certifying it precisely is useful.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 14, 'What should an Expert pass be used for on a real project?', '["Signing off the completion design in full.", "The geometric half of a completion review, with ratings and judgement brought from elsewhere.", "Selecting the tubing size, since the size matrix in this course is the calculation that determines what a well can carry.", "Reviewing the length change calculations supplied by the tubing designer, which this course is now qualified to check."]'::jsonb, 1, 'Bring this to whether the thing goes in, what gets through it, and where the seals land.'),
  ('completion', 'advanced', 'module', 'm05-the-edges', 15, 'What is the last thing this course says about the engine it teaches?', '["That the engine has been fully validated.", "That the engine should be rewritten, because a defect of that kind indicates a structural problem with how it was designed.", "That writing the course found a real defect in an output every user reads and no test checked.", "That the engine''s outputs should be treated as approximate, since one of them was wrong for as long as the module existed."]'::jsonb, 2, 'That is what a course is for, as much as the teaching.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 1, 'An interviewer asks what an Expert pass here means in practice. Which reply is accurate?', '["That you can design and specify a whole completion.", "That you can compute the four length change effects from the well conditions and check the tubing string against the result.", "That you can size a bore, compute the band, choose a landing and say what happens at both extremes.", "That you can select equipment, confirm its ratings and confirm its elastomer compatibility for the service the well will see."]'::jsonb, 2, 'Plus everything the first two tiers established about fit and volumes.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Three results from this tier are worth keeping. Which set is it?', '["The budget identity, the band, and the minimum bore length.", "The four length change effects and their signs.", "The three boundary conditions, the three verdicts and the two refusals the space out calculation applies to its inputs.", "The published landing, the published band and the shortfall between them, all measured on the golden job in the course."]'::jsonb, 0, 'One rules out a whole class of approach, one replaces a rule of thumb, and one sizes the hardware.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 3, 'A design lands the seals at the midpoint of the bore and a colleague objects. On what grounds?', '["The midpoint is never a valid landing.", "The midpoint is only right when the two cases are equal and opposite.", "The midpoint gives the least travel in both directions, since the available travel is maximised at either end of the bore.", "The midpoint cannot be achieved with pup joints, which come in increments that rarely divide the bore length evenly."]'::jsonb, 1, 'With unequal cases it gives each direction the same room for very different demands.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A completion warns on contraction and passes elongation comfortably. What is the one line diagnosis?', '["The bore is too short for the design cases.", "The margin has been set too high, since a case that passes with positive remaining travel is not a case that has failed.", "The two cases have been entered with the wrong signs, which is why one of them appears comfortable and the other does not.", "It is landed too shallow, and the elongation direction has slack the contraction direction needs."]'::jsonb, 3, 'Move it deeper by the shortfall and both are satisfied.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 5, 'A bore is specified at exactly the swing plus twice the margin. What has that bought?', '["Exactly one landing, with no tolerance on where the seals actually end up.", "A comfortable design with room to spare.", "A band half the width of the swing, since the two margins at the ends are what the band is made of in the first place.", "Nothing usable, because a band of zero width means no landing satisfies both cases and the bore is therefore too short."]'::jsonb, 0, 'Every metre beyond the minimum buys a metre of band, and at the minimum there is none.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 6, 'You are asked to specify a receptacle and the stimulation case is uncertain. Which way do you err?', '["Shorter, because precision machined pipe is expensive.", "Longer, because the cost of being short is discovered with the string in the hole.", "Neither; specify the exact minimum and manage the uncertainty by adjusting the landing on the rig once the cases are confirmed.", "Longer, but only if the uncertainty is in the elongation case, since that is the direction with the more serious failure mode."]'::jsonb, 1, 'The asymmetry of the two outcomes is why bores are specified generously.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 7, 'A well will never be stimulated. Should the stimulation case size the bore?', '["Yes, because every conceivable case should be carried.", "Yes, because a well that is not stimulated today may be stimulated in ten years and the completion cannot be changed then.", "No, provided that decision is made explicitly and recorded.", "It makes no difference, because the stimulation case is the largest contraction and the band would be empty without it anyway."]'::jsonb, 2, 'The converse error, leaving out a case that later happens, is the worse one.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 8, 'An argument pushes the landing outside the band. What does that mean?', '["The argument is correct and the band should be ignored.", "The margin is too large, and reducing it would widen the band enough to accommodate the landing that the argument requires.", "The case list is wrong, since a band that excludes a defensible landing must have been computed from the wrong cases.", "The bore is too short for the argument being made, and a longer bore is the answer."]'::jsonb, 3, 'None of the three reasons to move within the band justifies leaving it.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Casing and Tubing Design found that two of three cases stroked out. This tier carries all three. Is one of them wrong?', '["No; they answer different questions about the same string and the answers compose.", "Yes; the two results contradict each other directly.", "Yes; the other course used a smaller margin, which is why it reported a failure where this tier reports every case as passing.", "No; the other course used the wrong three cases, and this tier corrects them before computing the band for the same string."]'::jsonb, 0, 'A one and a half metre stroke really is insufficient. A long enough bore is not.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 10, 'Adding a third and more extreme case to a design narrows the band. Does it close it?', '["Yes, a third case always closes the band.", "Not necessarily; it narrows it by the increase in the swing, and it can stay open.", "No; a third case cannot narrow the band at all, because the band depends only on the largest case in each of the two directions.", "It depends on the sign of the third case, since a third contraction narrows the band and a third elongation widens it."]'::jsonb, 1, 'The three case band is narrower than the two case one and still comfortable.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 11, 'What is the single sentence summary of this course?', '["A study of the equipment used in a completion string.", "A method for computing four volumes and two clearances from a component list and a casing program for any well.", "A geometry problem with a path in it: what gets down, what gets through, and where you landed it.", "An examination of the loads a completion string experiences over its producing life and how the hardware absorbs them."]'::jsonb, 2, 'Each of the three clauses is one tier of the course.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Which course supplies what this one consumes, and which consumes what this one supplies?', '["Well Control supplies both and consumes neither.", "Torque and Drag supplies the length changes and Well Integrity consumes the clearances, since both concern the same string.", "Geomechanics supplies the casing program and Stimulation Design consumes the through bore of the finished completion.", "Casing and Tubing Design supplies the length changes; Perforation and Sand Control uses what sits below the packer."]'::jsonb, 3, 'Stimulation Design also designs the job that produces the largest contraction case in this tier.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 13, 'What is the one habit this course recommends carrying to any model?', '["Check a reported single worst case against the full list once by hand.", "Always compute every result twice.", "Never trust an output that has not been compared against an independent implementation written in a different language.", "Always run the calculation at the extremes of every input range before accepting any result from the middle of it."]'::jsonb, 0, 'If they disagree you have found something; if they agree you have learned what the tool means.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What would you do first to use this course on a real well?', '["Recompute the length changes from the well conditions.", "Get a real equipment catalog and rerun everything on it.", "Obtain a drift run from the well, since the catalog casing bores are the least reliable numbers in the whole calculation.", "Rewrite the engine against the vendor data model, since the representative catalog is structured differently from a real one."]'::jsonb, 1, 'Every calculation runs unchanged and every number moves.'),
  ('completion', 'advanced', 'module', 'm06-the-expert-reading', 15, 'And what would you get after that?', '["A second opinion on the tubing size.", "A survey of the well, so that the dogleg allowance this course does not model can be added to the clearance calculation.", "A drift run from the well itself, to compare against the casing program.", "The measured lengths of every joint, so that the tally used for the stack up matches the string that will actually be run."]'::jsonb, 2, 'The gap between the two is the thing this course keeps flagging and cannot compute.'),
  ('completion', 'advanced', 'final', null, 1, 'A well is produced hot for a year and then stimulated with a cold fluid. Which operation moves the string further?', '["The stimulation, because cooling below the static profile exceeds heating above it.", "The production, because it lasts far longer.", "Neither; the two produce length changes of similar magnitude in opposite directions on almost every completion string.", "It depends on the reservoir temperature, since a hot reservoir produces a larger heating case than any stimulation can cool."]'::jsonb, 0, 'That asymmetry is why contraction usually dominates a space out design.'),
  ('completion', 'advanced', 'final', null, 2, 'A tubing string is put on high rate injection. What does ballooning do to its length?', '["It lengthens it, because pressure acts downward on the shoe.", "Internal pressure swells it radially and therefore shortens it axially.", "It has no axial effect, because radial and axial strains are independent in a cylinder loaded only by internal pressure.", "It lengthens it in the upper part of the string and shortens it below, where the external pressure exceeds the internal one."]'::jsonb, 1, 'External pressure does the reverse, and both effects are smaller than the thermal one in most wells.'),
  ('completion', 'advanced', 'final', null, 3, 'A string goes into compression and buckles. What happens to its end to end length?', '["It lengthens, because the pipe is being compressed.", "It is unchanged, because buckling redistributes the pipe laterally without altering the distance between the two ends of it.", "It shortens further, because a helix is shorter than a straight line of the same pipe.", "It shortens, but only by the amount the steel is compressed axially, which is negligible compared with the thermal effect."]'::jsonb, 2, 'It is the nonlinear one of the four, and it interacts directly with the space out.'),
  ('completion', 'advanced', 'final', null, 4, 'A completion engineer asks this engine for the length change of a string. What comes back?', '["A thermal length change from the geothermal gradient.", "The total of all four effects, computed from the well conditions supplied together with the completion string description.", "A refusal, naming the missing temperature profile, which is the only input the calculation would need in order to proceed.", "Nothing; it takes a length change as an input rather than computing one."]'::jsonb, 3, 'Computing it needs a temperature profile, a pressure profile, a fluid density and a survey.'),
  ('completion', 'advanced', 'final', null, 5, 'Three length changes are borrowed from another course. What is their shape?', '["One elongation and two contractions, the largest of which is a contraction.", "Two elongations and one contraction.", "Three contractions of increasing magnitude, since every operation on that well cools the string below its static temperature.", "One elongation, one contraction and one case that produces no net movement at all, where the four effects cancel."]'::jsonb, 0, 'The swing across them is a little over four metres.'),
  ('completion', 'advanced', 'final', null, 6, 'A design anchors the tubing to the packer. What has that decision bought and cost?', '["A longer completion life, at no cost at all.", "Simplicity, at the cost of turning the length change into a force the string has to survive.", "The ability to hold pressure in both directions, at the cost of a larger packer body and therefore a tighter clearance.", "A shorter string, at the cost of having to compute the buckling behaviour before the completion can be run in the well."]'::jsonb, 1, 'The benefit is that there are no moving seals and nothing to space out.'),
  ('completion', 'advanced', 'final', null, 7, 'A seal arrangement with a one and a half metre stroke is proposed for a string whose swing is four metres. What happens?', '["Every case is carried comfortably.", "The seals come out of the bore under every case, because a stroke shorter than the swing offers no travel in either direction.", "Two of the three cases stroke out, and the string loads up when they do.", "The string is free under production and anchored under injection, which is an acceptable design in most jurisdictions."]'::jsonb, 2, 'That is precisely what the other course found, and it is a correct result about that arrangement.'),
  ('completion', 'advanced', 'final', null, 8, 'A completion is free under production and anchored during a stimulation. Is that a design fault?', '["No; every completion behaves that way.", "Yes; a completion must be in the same regime for every operation, otherwise the load path changes and cannot be analysed.", "No; the anchored regime is the safe one, so a completion that becomes anchored during a severe job is being protected by it.", "It is a design case that has not been carried, and the stimulation is when the loads are largest."]'::jsonb, 3, 'That is why the design case is nearly always the coldest one and not the normal one.'),
  ('completion', 'advanced', 'final', null, 9, 'Seals are landed two metres into a five metre bore. How much travel does each direction have?', '["Two metres for contraction and three for elongation.", "Two and a half metres in each direction.", "Three metres for contraction and two for elongation, since contraction is measured from the seals to the bottom of the bore.", "Five metres in each direction, because the seals may travel the whole bore in either direction from wherever they start."]'::jsonb, 0, 'Contraction consumes the insertion depth and elongation consumes what is below the seals.'),
  ('completion', 'advanced', 'final', null, 10, 'A rig hand asks how the insertion depth is actually set. What do you say?', '["By a setting tool run after the packer is set.", "By the accumulated length of everything above the seals, adjusted with pup joints.", "By landing the tubing hanger at one of several available elevations in the wellhead, each of which gives a different depth.", "By the packer setting depth, which is chosen so that the seals land where the design intended once the string is made up."]'::jsonb, 1, 'To land two metres deeper, you add two metres of pipe above.'),
  ('completion', 'advanced', 'final', null, 11, 'A string measures a metre longer than the tally predicted. What does that do to the design?', '["It has no effect, since the extra length is above the seals.", "It shortens the available travel in both directions by half a metre each, which reduces the margin symmetrically.", "It unbalances it: one direction gains a metre and the other loses one.", "It moves the packer a metre deeper, since the extra length pushes the whole assembly down the hole as it is run in."]'::jsonb, 2, 'And the direction it is unbalanced towards is usually the one that matters most.'),
  ('completion', 'advanced', 'final', null, 12, 'State the identity that governs the whole tier.', '["The two available travels are always equal.", "The sum of the two available travels equals the swing plus twice the margin, which is the shortest usable bore length.", "The product of the two available travels is maximised at the midpoint, which is what makes the midpoint the standard landing.", "The two available travels sum to the receptacle length at every landing."]'::jsonb, 3, 'It is exactly true and it is easy to forget when a deeper landing feels safer.'),
  ('completion', 'advanced', 'final', null, 13, 'Somebody says landing deeper is simply safer. What is wrong with that?', '["It buys security against one failure and spends exactly the same amount against the other.", "Nothing; a deeper landing is always safer.", "It is wrong only when the elongation case is the larger of the two, in which case landing deeper reduces the margin against it.", "A deeper landing cannot be achieved once the string is made up, so the statement describes something that is not available."]'::jsonb, 0, 'The exchange rate between the two directions is exactly one.'),
  ('completion', 'advanced', 'final', null, 14, 'Which of available, used and remaining depends on both the hardware and the operation?', '["Available, which depends on the landing and the bore.", "Remaining, which is available less used.", "Used, which is the magnitude of the length change and therefore depends on the operation and on the string that undergoes it.", "All three, since none of them can be computed without both the landing depth and the case magnitude being known first."]'::jsonb, 1, 'It is the number the verdict is based on.'),
  ('completion', 'advanced', 'final', null, 15, 'A case has positive remaining travel below the margin. What is the verdict and what does it mean?', '["A failure: the seals leave the bore during the case.", "A pass with a note, since a positive remaining travel means the case is carried and the margin is advisory rather than binding.", "A warning: the design works on the numbers and has less room than it asked for.", "Undefined, because a margin larger than the remaining travel cannot be applied to that case in a meaningful way."]'::jsonb, 2, 'It is not a prediction of failure.'),
  ('completion', 'advanced', 'final', null, 16, 'A data sheet gives a receptacle of zero length and a seal stack landed below its shoe. What does the tool do?', '["A negative length change and a zero margin.", "A length change larger than the bore length, and an insertion depth of zero, both of which describe an unusable landing.", "Two cases with the same sign, and a margin larger than half the bore, neither of which can produce a usable band.", "An insertion deeper than the bore, and a bore of zero length or less."]'::jsonb, 3, 'Both describe nothing physical, which is the same test the stack up applies.'),
  ('completion', 'advanced', 'final', null, 17, 'A string lengthens by more than the travel below the seals. What is the failure?', '["The seals come out of the top of the bore.", "The assembly shoulders at the bottom and the string starts loading up in compression.", "The packer unseats, because the compressive load transferred through the shoulder exceeds what the slips are able to carry.", "The seal stack extrudes, because the pressure differential across it rises sharply once the movement is arrested."]'::jsonb, 1, 'It is a transition from free to anchored, and often survivable.'),
  ('completion', 'advanced', 'final', null, 18, 'The seals are pulled up past the top of the receptacle. What has the well lost?', '["The seals shoulder at the top of the bore.", "The string goes into tension against the packer, and the connection between the two has to carry the resulting load.", "The polished bore is damaged as the seals drag across its upper edge, but integrity is maintained until the next workover.", "The seals leave the bore and the tubing to annulus seal is lost."]'::jsonb, 3, 'There is no shoulder to stop them and nothing to load up against.'),
  ('completion', 'advanced', 'final', null, 19, 'Why does the contraction failure not announce itself?', '["Because it happens during a job with pumps running and shows only as pressure where it should not be.", "Because the seals are not instrumented.", "Because it happens slowly over the producing life of the well, so no single event marks the point at which integrity is lost.", "Because the surface pressure reading is dominated by the pump pressure, which masks any change in the annulus pressure."]'::jsonb, 0, 'It is a containment failure at the moment of maximum cooling.'),
  ('completion', 'advanced', 'final', null, 20, 'You sweep the landing and plot the two remaining travels. What is the horizontal line on the same axes?', '["The margin.", "The larger of the two case magnitudes, which does not change with the landing and therefore plots as a horizontal line.", "The sum of the two available travels, at the bore length.", "The band width, which is fixed by the bore and the two requirements and is therefore independent of where the seals land."]'::jsonb, 2, 'That flat line is the whole tier in one picture.'),
  ('completion', 'advanced', 'final', null, 21, 'Contraction dominates on your well. Where on the sweep chart do the two lines meet?', '["Deeper than the midpoint of the bore.", "Exactly at the midpoint of the bore.", "Shallower than the midpoint, because the contraction direction needs more room and a shallower landing supplies it.", "At the lower edge of the band, which is where the contraction case first becomes acceptable with the stated margin."]'::jsonb, 0, 'The crossing is where the two are equally comfortable rather than equally supplied.'),
  ('completion', 'advanced', 'final', null, 22, 'A landing is moved deeper to cure a contraction warning and the elongation case still passes. Why did that work?', '["Because a deeper landing improves both directions.", "Because there was slack in the elongation direction, not because the move was free.", "Because the elongation case is smaller and therefore always passes whatever the landing is, provided the bore is long enough.", "Because moving the landing changes the available travel without changing the budget, which is what makes the move possible."]'::jsonb, 1, 'The elongation case lost exactly what the contraction case gained.'),
  ('completion', 'advanced', 'final', null, 23, 'Write down the lower edge of the band.', '["The elongation magnitude plus the margin.", "The bore length less the elongation magnitude and less the margin, which is the deepest permissible landing rather than the shallowest.", "The contraction magnitude plus the margin.", "Half the bore length, since the band is centred on the midpoint whatever the two case magnitudes turn out to be."]'::jsonb, 2, 'The contraction case sets a lower bound on the insertion depth.'),
  ('completion', 'advanced', 'final', null, 24, 'You have both edges and want to quote a tolerance on the landing. What do you compute?', '["The difference between the two case magnitudes.", "The bore length less twice the margin, since the margins at the two ends are the only part of the bore that is unusable.", "The sum of the two remaining travels at the midpoint, which is what is left over once both cases have been absorbed.", "The bore length less the sum of the two requirements."]'::jsonb, 3, 'Checking the width against the two edges catches a sign error in either of them.'),
  ('completion', 'advanced', 'final', null, 25, 'The band comes out empty. What are the three fixes?', '["A longer bore, a smaller margin, or a shorter design case list.", "A different landing, a different packer, or a longer string.", "Recompute the length changes, re measure the joints, or land the seals at the midpoint of the bore as a compromise.", "Increase the insertion depth, decrease the insertion depth, or accept the failure and monitor the annulus pressure."]'::jsonb, 0, 'It is a hardware problem rather than a landing problem.'),
  ('completion', 'advanced', 'final', null, 26, 'Why does the engine bisect for the band instead of solving the two inequalities?', '["Because the inequalities have no closed form solution.", "Because bisection does not assume the analytic form and would survive a nonlinearity.", "Because bisection is faster, since the closed form requires several conditional branches to handle the edge cases correctly.", "Because the predicate is discontinuous at the band edges, and a closed form cannot represent a discontinuous boundary."]'::jsonb, 1, 'It is slower and it has that one advantage worth having.'),
  ('completion', 'advanced', 'final', null, 27, 'A band is ten centimetres wide. What does that tell the rig?', '["That the bore is longer than it needs to be.", "That the two cases are nearly equal in magnitude, since a narrow band arises when the two requirements are close together.", "That the pup joint selection has to be right, because there is almost no tolerance.", "That the landing should be placed at the shallow edge, since a narrow band leaves no room to favour either direction."]'::jsonb, 2, 'A band a metre wide means the space out can be half a metre out either way.'),
  ('completion', 'advanced', 'final', null, 28, 'For the published job the midpoint of the bore is below the lower band edge. What follows?', '["The band has been computed incorrectly.", "The bore is too short, since a band that excludes the midpoint cannot contain any landing that is achievable in practice.", "The margin is too large, since a correctly chosen margin always leaves the midpoint of the bore inside the resulting band.", "The rule of thumb landing fails the contraction condition on that job."]'::jsonb, 3, 'That is the striking result of the module.'),
  ('completion', 'advanced', 'final', null, 29, 'The published landing is three tenths of a metre shallower than its band. What is the corresponding statement about the remaining travel?', '["The contraction remaining falls three tenths of a metre short of the margin.", "The contraction case fails by three tenths of a metre.", "The elongation remaining exceeds the margin by three tenths of a metre, which is the slack available in the other direction.", "The band is three tenths of a metre narrower than it would be if the landing had been placed at the middle of the bore."]'::jsonb, 0, 'They are the same fact seen from two sides.'),
  ('completion', 'advanced', 'final', null, 30, 'A reviewer calls the golden space out job unacceptable. Is that fair?', '["Yes; the seals leave the bore under the contraction case.", "No; it works, and it does not deliver the margin the design stated for itself.", "Yes; a landing outside the band is by definition unacceptable, whatever the remaining travel happens to work out to be.", "No; the margin is advisory, so a landing that delivers less than it is fully compliant with the design as written."]'::jsonb, 1, 'The margin was stated and not enforced, which is a different failing from a completion that does not work.'),
  ('completion', 'advanced', 'final', null, 31, 'Derive the shortest usable bore from the physics rather than from the band.', '["The bore must equal the larger case plus the margin.", "The bore must equal twice the larger case magnitude, which guarantees room in both directions whichever case dominates.", "The seals must stay inside at both extremes with a margin, and they travel the swing between them.", "The bore must equal the sum of the two case magnitudes, since the margins are already contained within the swing itself."]'::jsonb, 2, 'So the bore must contain the swing plus a margin at each end, which is the same answer the band gives.'),
  ('completion', 'advanced', 'final', null, 32, 'A bore is ordered one metre longer than the minimum. What has that metre bought?', '["One metre of extra travel in each direction.", "Half a metre of extra travel in each direction, since the extra length is divided between the two ends of the receptacle.", "Nothing, since a bore longer than the minimum leaves travel that neither of the two design cases will ever make use of.", "One metre of band, which is one metre of tolerance on where the seals land."]'::jsonb, 3, 'Which is why bores are specified generously.'),
  ('completion', 'advanced', 'final', null, 33, 'The three borrowed cases have a swing of a little over four metres. Is a six point one metre bore enough?', '["Yes; the band is open and about eighty six centimetres wide.", "No; the swing exceeds the bore length.", "Only if the margin is reduced below half a metre, since at half a metre the requirements exceed the available bore length.", "Only for two of the three cases, since the third exceeds the travel available in its direction at every possible landing."]'::jsonb, 0, 'Land in the middle of that band and all three cases pass with margin.'),
  ('completion', 'advanced', 'final', null, 34, 'Casing and Tubing Design says two cases stroke out; this tier says all three are carried. Which is wrong?', '["The other course, which used the wrong three cases.", "Neither; they answer different questions and the answers compose.", "This tier, which uses a longer bore than the string was actually completed with and therefore reports an optimistic result.", "Both, since a string cannot simultaneously stroke out of a seal arrangement and be carried by a polished bore receptacle."]'::jsonb, 1, 'A one and a half metre stroke really is insufficient; a long enough bore is not.'),
  ('completion', 'advanced', 'final', null, 35, 'Which calculation in this course is completely independent of the equipment catalog?', '["The drift table, which comes from the specification.", "The through bore, which uses only the inside diameters and therefore does not depend on the approximate outside ones.", "The space out, which reads a bore length, a landing and two length changes.", "The volumes, which are computed from lengths and casing bores rather than from any equipment dimension at all."]'::jsonb, 2, 'Its results are unconditional: the identity, the band and the minimum bore length are arithmetic.'),
  ('completion', 'advanced', 'final', null, 36, 'The warn margin and the design case list are both inputs. What do they have in common?', '["Both are defined by the API specification.", "Both are computed by the engine from the casing program and the string, and then presented for the user to confirm.", "Both affect only the space out calculation, since the clearance check applies its margin without reference to either of them.", "Both need information about the well and the operator that the model does not carry."]'::jsonb, 3, 'Computing the consequence precisely and leaving the choice to the reader is the more useful division.'),
  ('completion', 'advanced', 'final', null, 37, 'You are asked which missing effect would most disturb a landing calculation. What do you name?', '["Buckling, because it changes the length change the space out has to absorb.", "Flow and erosion velocity in the tubing.", "Deviation, because a deviated string moves along the hole rather than vertically and the seals therefore travel less than computed.", "Time, because the seal elements degrade over the producing life and the effective travel available reduces as they do."]'::jsonb, 0, 'It is nonlinear and it needs the axial force distribution, which needs the loads above it.'),
  ('completion', 'advanced', 'final', null, 38, 'A reviewer asks whether the Expert certificate qualifies somebody to design a completion. What is the answer?', '["Yes; the three tiers cover the whole subject.", "No; it certifies the geometric half, and ratings, materials and judgement come from elsewhere.", "Yes for a cased hole completion, and no for an open hole one, since the course models only the cased case throughout.", "No; it certifies the ability to check a completion design produced by somebody else, and not to produce one at all."]'::jsonb, 1, 'A wide claim on the strength of a geometry course would be worth less than nothing.'),
  ('completion', 'advanced', 'final', null, 39, 'You are handed an unfamiliar engineering model. What does this course suggest you do first?', '["Compare its outputs against a second implementation.", "Run it at the extremes of every input range, since defects are most likely to appear where the inputs are least typical.", "Find a reported single worst case and check it against the detail by hand.", "Read the validation report and confirm that every golden case in it has been reproduced to the stated tolerance."]'::jsonb, 2, 'The summaries get read by every user and tested by nobody.'),
  ('completion', 'advanced', 'final', null, 40, 'A completion is landed, produced for ten years and then stimulated. What has this course told you to check before the job?', '["That the packer is still holding pressure.", "That the through bore is large enough for the coiled tubing that the stimulation job will need to run into the well.", "That the clearance of every component is still positive, given the scale that has accumulated over ten years of production.", "That the stimulation case was on the design list when the bore and the landing were chosen."]'::jsonb, 3, 'If it was not, the seals may not have the travel the job will demand of them.'),
  ('completion', 'advanced', 'final', null, 41, 'Summarise the whole course in one sentence.', '["A geometry problem with a path in it: what gets down, what gets through, and where you landed it.", "A study of completion equipment and its dimensions.", "A method for integrating four volumes and two fit checks from a component list and a casing program for any cased well.", "An analysis of the loads a completion string experiences and of the hardware arrangements that absorb them safely."]'::jsonb, 0, 'Each clause is one tier.'),
  ('completion', 'advanced', 'final', null, 42, 'A student asks what the course itself contributed back to the engine. What is the answer?', '["That the engine has now been fully validated.", "That writing it found a real defect in an output every user reads and no test checked.", "That the engine''s outputs should be treated as approximate, since one of them was wrong for as long as the module existed.", "That the engine should be rewritten, because a defect of that kind points to a structural problem in how it was built."]'::jsonb, 1, 'That is what a course is for, as much as the teaching.');
